import {
  authorizeUser,
  AuthConfigService,
  ApiService,
  UserAttributesManager,
} from '@mesx/common-ui-lib';
import { WebStorageStateStore } from 'oidc-client';
import { defineStore } from 'pinia';
import { useRouter } from 'vue-router';
import { AuthConfigDTO } from '../../types/auth.config.dto.ts';
import { appLogger } from '../../utils/logger/app-logger';
import { configuration } from '../configuration.ts';
import { useUserStore } from './user-store.ts';
import { getUser ,User} from '../user-service.ts';


interface State {
  managedBy: string
  profile: string
  user: User | undefined
  userAttributes: Record<string, string>
}
const authconfig = new AuthConfigDTO(
  configuration.getAuthority(),
  configuration.getClientId(),
  configuration.getRedirectUri(),
  configuration.getResponseType(),
  configuration.getScopes(),
  new WebStorageStateStore({ store: globalThis.sessionStorage }),
  configuration.getAccessTokenExpiringNotificationTime(),
);
const umeBaseUrl = import.meta.env.UME_API_URL as string;
const appName = 'EQUIPEMENT-SCREEN';
const token = import.meta.env.TOKEN as string;
const redirectUri: string = (import.meta.env.APP_REDIRECT_URI as string | undefined) ?? '';
let appBasePath: string;
if (redirectUri !== '') {
  const parts: Array<string> = redirectUri.split('/');
  appBasePath = parts.pop() ?? '';
}
const authService = new AuthConfigService(authconfig);
const apiService = new ApiService(umeBaseUrl, token, appName);
const userAttributesManager = new UserAttributesManager(apiService);
export const useProfileStore = defineStore('user', {
  actions: {
    async authenticateUser() {
      const useUser = useUserStore();
      const user = await getUser();
      if (!user) {
        appLogger.error('User not found');
        return;
      }
      const { profile } = user;
      const fetchedUser = await apiService.getUserByEmail(profile.email);
      if (fetchedUser !== null && fetchedUser !== undefined) {
        localStorage.setItem('userId', fetchedUser.userId);
        await apiService.updateUserLastLoginByEmail(
          fetchedUser.email,
          new Date(),
        );
      }
      else {
        const userDetails = {
          firstName: profile.given_name,
          lastName: profile.family_name,
          email: profile.email,
          lastLogin: new Date(),
        };
        await apiService.saveUser(userDetails);
      }
      useUser.setProfile(
        `${profile.given_name} ${profile.family_name}`,
      );
    },
    async authorizeUser() {
      const router = useRouter();
      const user = await getUser();
      if (user) {
        const roleNamesString = user.profile.groups.join(',');
        await authorizeUser(apiService, roleNamesString, router, appBasePath);
      }
    },
    async fetchUserAttributes() {
      try {
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes
          = userAttributesManager.transformAttributesToStorageFormat(attributes);
        if (userAttributes !== null && userAttributes !== undefined) {
          this.userAttributes = { ...userAttributes };
        }
        else {
          appLogger.warn('No user attributes found.');
        }
      }
      catch (error: unknown) {
        appLogger.error(`Error fetching user attributes: ${error instanceof Error ? error.message : String(error)}`);
      }
    },
    async getUser(): Promise<User | undefined> {
      if (this.user) {
        return this.user;
      }
      const user = await getUser();
      if (user) {
        this.user = user;
      }
      return user;
    },
    async initializeAuthentication() {
      const router = useRouter();
      await authService.initializeAuthentication(router);
    },
    async isAuthenticated(): Promise<boolean> {
      return authService.isAuthenticated();
    },
    async logout() {
      try {
        await authService.logout();
        localStorage.removeItem('userAuth');
        localStorage.removeItem('userAttributes');
      }
      catch {
        appLogger.error('Log out failed');
      }
    },
  },

  persist: {
    key: 'userAttributes',
    paths: ['userAttributes'],
  },
  state: (): State => ({
    managedBy: '',
    profile: '',
    userAttributes: {} as Record<string, string>,
    user: undefined as User | undefined,
  }),
});

