import batchRelatedWorkItemsView from '@/work-item-trace/views/batch-related-work-items-view.vue';
import batchWorkItemsView from '@/work-item-trace/views/batch-work-items-view.vue';
import relatedWorkItemGraphView from '@/work-item-trace/views/related-work-item-graph-view.vue';

const routes = [
  {
    component: unauthorized,

    name: 'Unauthorized',
    path: '/unauthorized',
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: '/loading',
  },
  {
    component: relatedWorkItemGraphView,
    meta: {
      requiresAuth: true,titleBoardKey: 'trace.related.pageTitle',
    },
    name: 'RelatedWorkItemTrace',
    path: '/cnerr-ui/trace/workitem-related',
  },
  {
    component: batchWorkItemsView,
    meta: {
     requiresAuth: true, titleBoardKey: 'trace.batch.pageTitle',
    },
    name: 'BatchWorkItemTrace',
    path: '/cnerr-ui/trace/workitem-batch',
  },
  {
    component: batchRelatedWorkItemsView,
    meta: {
      requiresAuth: true, titleBoardKey: 'trace.batch.relatedItemsTitle',
    },
    name: 'BatchRelatedWorkItemTrace',
    path: '/cnerr-ui/trace/workitem-batch-related',
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }

  const userAuth = useProfileStore();

  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes();
        await userAuth.authorizeUser();
      }
      else {
        console.error('User not found');
        return next('/unauthorized');
      }
      return next();
    }
    catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next('/unauthorized');
    }
  }

  return next();
});

