import { storeToRefs } from 'pinia';
import { computed, onMounted, ref } from 'vue';
import type { ComputedRef, Ref } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRoute, useRouter } from 'vue-router';
import {
  groupCommitIdsByRepo,
  mergeCommitTagResults,
} from '@/work-item-trace/helpers/commit-tag-helpers.ts';
import {
  getCommitTagsBatch,
  splitCommitIds,
} from '@/work-item-trace/services/trace-api.service.ts';
import { useTraceStore } from '@/work-item-trace/store/trace-store.ts';
import type {
  CommitWithTags,
  RelatedWorkItemsData,
} from '@/work-item-trace/types/trace-api.types.ts';
import type { DecisionInputPayload } from '@/work-item-trace/types/decision-dashboard.types';

interface RepoCommitGroup {
  commits: Array<CommitWithTags>;
  repositoryName: string;
}

interface UseBatchRelatedResultsReturn {
  decisionPayload: ComputedRef<DecisionInputPayload | undefined>;
  errorMessage: Ref<string>;
  handleBackToSelection: () => void;
  isFetching: Ref<boolean>;
  loadingRepos: Ref<Set<string>>;
  localErrorMessage: Ref<string>;
  projectInput: Ref<string>;
  relatedResults: Ref<Array<RelatedWorkItemsData>>;
  sortedRelatedResults: ComputedRef<Array<RelatedWorkItemsData>>;
  sortedRepoEntries: ComputedRef<Array<RepoCommitGroup>>;
  totalDiscoveredCommits: Ref<number>;
  workItemIds: Ref<Array<number>>;
}

const SKIPPED_TAG_REPOSITORIES = new Set(['mesx-infrastructure']);

/**
 * Manage batch related-results page state and data loading.
 * @returns Reactive state and handlers for the batch related-results view.
 */
export function useBatchRelatedResults(): UseBatchRelatedResultsReturn {
  const route = useRoute();
  const router = useRouter();
  const traceStore = useTraceStore();
  const { t } = useI18n();
  const { errorMessage } = storeToRefs(traceStore);

  const allCommitsByRepo = ref<Map<string, Array<CommitWithTags>>>(new Map());
  const isFetching = ref(false);
  const loadingRepos = ref<Set<string>>(new Set());
  const localErrorMessage = ref('');
  const projectInput = ref('');
  const relatedResults = ref<Array<RelatedWorkItemsData>>([]);
  const totalDiscoveredCommits = ref(0);
  const workItemIds = ref<Array<number>>([]);

  const sortedRelatedResults = computed(() =>
    [...relatedResults.value].sort((left, right) => {
      if (right.commitCount !== left.commitCount) {
        return right.commitCount - left.commitCount;
      }

      if (right.relatedCount !== left.relatedCount) {
        return right.relatedCount - left.relatedCount;
      }

      return left.workItemId - right.workItemId;
    }),
  );

  const decisionPayload = computed<DecisionInputPayload | undefined>(() => {
    if (isFetching.value || relatedResults.value.length === 0) {
      return undefined;
    }

    const workItemMap = new Map<number, { id: number; state?: string | null }>();
    for (const result of relatedResults.value) {
      for (const wi of result.workItems) {
        if (!workItemMap.has(wi.id)) {
          workItemMap.set(wi.id, { id: wi.id, state: wi.state ?? null });
        }
      }
    }

    const repositories: DecisionInputPayload['repositories'] = [];
    for (const [repositoryName, commits] of allCommitsByRepo.value.entries()) {
      const commitInputs = commits
        .filter(
          (c) =>
            c.tagBefore.length > 0 ||
            c.tagAfter.length > 0 ||
            c.exactTags.length > 0,
        )
        .map((c) => ({
          commitId: c.commitId,
          tagBefore: c.tagBefore,
          tagAfter: c.tagAfter,
          exactTags: c.exactTags,
        }));

      if (commitInputs.length > 0) {
        repositories.push({ repositoryName, commits: commitInputs });
      }
    }

    return {
      workItems: [...workItemMap.values()],
      repositories,
    };
  });

  const sortedRepoEntries = computed<Array<RepoCommitGroup>>(() =>
    [...allCommitsByRepo.value.entries()]
      .sort(([leftRepo, leftCommits], [rightRepo, rightCommits]) => {
        if (rightCommits.length !== leftCommits.length) {
          return rightCommits.length - leftCommits.length;
        }

        return leftRepo.localeCompare(rightRepo);
      })
      .map(([repositoryName, commits]) => ({ commits, repositoryName })),
  );

  /**
   * Extract and validate route query parameters.
   * @returns True when the current query parameters are valid.
   */
  function parseQueryParameters(): boolean {
    const { project, workItemIds: idsParameter } = route.query;

    if (!project || typeof project !== 'string') {
      localErrorMessage.value = t('trace.validation.missingProject');
      return false;
    }

    if (!idsParameter || typeof idsParameter !== 'string') {
      localErrorMessage.value = t('trace.validation.missingWorkItemIds');
      return false;
    }

    projectInput.value = project;

    const parsedIds = idsParameter
      .split(',')
      .map((id) => Number.parseInt(id, 10))
      .filter((id) => !Number.isNaN(id) && id > 0);

    if (parsedIds.length === 0) {
      localErrorMessage.value = t('trace.validation.invalidWorkItemIds');
      return false;
    }

    workItemIds.value = parsedIds;
    return true;
  }

  /**
   * Update the total discovered commit count for the current result set.
   */
  function updateBatchCommitTotals(): void {
    totalDiscoveredCommits.value = relatedResults.value.reduce(
      (commitCount, result) => commitCount + result.commits.length,
      0,
    );
  }

  /**
   * Load tags for one repository worth of commits.
   * @param repositoryName Repository name.
   * @param commitIds Commit ids to resolve.
   * @returns Loaded commit tag entries.
   */
  async function loadRepositoryTags(
    repositoryName: string,
    commitIds: Array<string>,
  ): Promise<Array<CommitWithTags>> {
    if (
      SKIPPED_TAG_REPOSITORIES.has(repositoryName) ||
      commitIds.length === 0
    ) {
      return [];
    }

    const nextLoadingRepos = new Set(loadingRepos.value);
    nextLoadingRepos.add(repositoryName);
    loadingRepos.value = nextLoadingRepos;

    try {
      const batches = splitCommitIds(commitIds);
      const responses = await Promise.allSettled(
        batches.map(async (batch) =>
          getCommitTagsBatch(batch, projectInput.value, repositoryName),
        ),
      );
      const commitsWithTags: Array<CommitWithTags> = [];

      for (const response of responses) {
        if (response.status === 'fulfilled' && response.value.success) {
          for (const [commitId, tagData] of Object.entries(
            response.value.results,
          )) {
            commitsWithTags.push({
              commitId,
              ...tagData,
            });
          }
        }
      }

      return commitsWithTags;
    } finally {
      const nextLoadingReposAfterLoad = new Set(loadingRepos.value);
      nextLoadingReposAfterLoad.delete(repositoryName);
      loadingRepos.value = nextLoadingReposAfterLoad;
    }
  }

  /**
   * Load and merge repository tags for all discovered commits.
   * @param nextResults Loaded related work item results.
   */
  async function loadAllRepositoryTags(
    nextResults: Array<RelatedWorkItemsData>,
  ): Promise<void> {
    const commitsByRepo = groupCommitIdsByRepo(
      nextResults.flatMap((result) => result.commits),
    );
    const tagGroups = await Promise.allSettled(
      [...commitsByRepo.entries()].map(async ([repositoryName, commitIds]) => ({
        commits: await loadRepositoryTags(repositoryName, commitIds),
        repositoryName,
      })),
    );
    const nextCommitsByRepo = new Map<string, Array<CommitWithTags>>();

    for (const tagGroup of tagGroups) {
      if (
        tagGroup.status === 'fulfilled' &&
        tagGroup.value.commits.length > 0
      ) {
        const existingCommits =
          nextCommitsByRepo.get(tagGroup.value.repositoryName) ?? [];

        nextCommitsByRepo.set(
          tagGroup.value.repositoryName,
          mergeCommitTagResults(existingCommits, tagGroup.value.commits),
        );
      }
    }

    allCommitsByRepo.value = nextCommitsByRepo;
  }

  /**
   * Load related work items and repository tags for the current query.
   */
  async function loadRelatedResults(): Promise<void> {
    if (workItemIds.value.length === 0) {
      return;
    }

    localErrorMessage.value = '';
    relatedResults.value = [];
    allCommitsByRepo.value = new Map();
    totalDiscoveredCommits.value = 0;
    loadingRepos.value = new Set();
    isFetching.value = true;

    try {
      const results = await Promise.all(
        workItemIds.value.map(async (workItemId) =>
          traceStore.fetchRelatedWorkItemsResult(
            workItemId,
            projectInput.value,
          ),
        ),
      );
      const nextResults = results
        .filter(
          (result): result is RelatedWorkItemsData => result !== undefined,
        )
        .sort(
          (left, right) =>
            workItemIds.value.indexOf(left.workItemId) -
            workItemIds.value.indexOf(right.workItemId),
        );

      relatedResults.value = nextResults;
      updateBatchCommitTotals();

      if (nextResults.length > 0) {
        await loadAllRepositoryTags(nextResults);
      }
    } catch {
      localErrorMessage.value = t('trace.common.loadingError');
    } finally {
      isFetching.value = false;
    }
  }

  /**
   * Navigate back to the batch stream page.
   */
  function handleBackToSelection(): void {
    router.push({
      name: 'BatchWorkItemTrace',
      query: {
        project: projectInput.value,
      },
    });
  }

  onMounted(() => {
    if (parseQueryParameters()) {
      loadRelatedResults().catch(() => {
        localErrorMessage.value = t('trace.common.loadingError');
      });
    }
  });

  return {
    decisionPayload,
    errorMessage,
    handleBackToSelection,
    isFetching,
    loadingRepos,
    localErrorMessage,
    projectInput,
    relatedResults,
    sortedRelatedResults,
    sortedRepoEntries,
    totalDiscoveredCommits,
    workItemIds,
  };
}

import { storeToRefs } from 'pinia';
import type { QTableColumn } from 'quasar';
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { useTraceStore } from '@/work-item-trace/store/trace-store.ts';

export interface StreamWorkItemRow {
  batchLabel: string;
  rowKey: string;
  status: string;
  timestamp: string;
  title: string;
  type: string;
  workItemId: number;
}

/**
 * Parse a positive integer from a number or string value.
 * @param value Candidate value.
 * @returns Positive integer or undefined.
 */
function toPositiveInteger(value: unknown): number | undefined {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return value;
  }

  if (typeof value === 'string') {
    const parsed = Number.parseInt(value, 10);

    if (!Number.isNaN(parsed) && parsed > 0) {
      return parsed;
    }
  }

  return undefined;
}

/**
 * Convert a raw stream record into a typed table row.
 * @param record Raw work item payload from the SSE stream.
 * @param rowIndex Position in the stream array used to produce a unique key.
 * @param t i18n translation function.
 * @returns Typed row or undefined when the record lacks a valid work item id.
 */
function toStreamRow(
  record: Record<string, unknown>,
  rowIndex: number,
  t: (key: string) => string,
): StreamWorkItemRow | undefined {
  const workItemId =
    toPositiveInteger(record.workItemId) ??
    toPositiveInteger(record.workitemId) ??
    toPositiveInteger(record.id);

  if (!workItemId) {
    return undefined;
  }

  const status =
    (typeof record.status === 'string' && record.status.trim()) ||
    (typeof record.state === 'string' && record.state.trim()) ||
    t('trace.batch.statusUnknown');

  const batchNumber =
    toPositiveInteger(record.streamBatchNumber) ??
    toPositiveInteger(record.batchNumber) ??
    toPositiveInteger(record.batch) ??
    1;

  const timestampSource =
    (typeof record.streamReceivedAt === 'string' && record.streamReceivedAt) ||
    (typeof record.timestamp === 'string' && record.timestamp) ||
    (typeof record.changedDate === 'string' && record.changedDate) ||
    '';

  const timestamp =
    timestampSource.length > 0
      ? new Date(timestampSource).toLocaleString()
      : t('trace.common.notAvailable');

  return {
    batchLabel: String(batchNumber),
    rowKey: `workitem-${workItemId}-${rowIndex}`,
    status,
    timestamp,
    title:
      (typeof record.title === 'string' && record.title.trim()) ||
      (typeof record.name === 'string' && record.name.trim()) ||
      t('trace.common.notAvailable'),
    type:
      (typeof record.type === 'string' && record.type.trim()) ||
      (typeof record.workItemType === 'string' && record.workItemType.trim()) ||
      t('trace.common.notAvailable'),
    workItemId,
  };
}

export interface UseBatchStreamReturn {
  availableStatuses: ReturnType<typeof computed<Array<string>>>;
  connectionStateLabel: ReturnType<typeof computed<string>>;
  errorMessage: ReturnType<typeof ref<string>>;
  handleClearSelection: () => void;
  handleClearStreamData: () => void;
  handleConnectStream: (
    localErrorReference: ReturnType<typeof ref<string>>,
  ) => void;
  handleDisconnectStream: () => void;
  isBusy: ReturnType<typeof computed<boolean>>;
  selectedRows: ReturnType<typeof ref<Array<StreamWorkItemRow>>>;
  selectedWorkItems: ReturnType<typeof computed<Array<StreamWorkItemRow>>>;
  streamBatchesProcessed: ReturnType<typeof ref<number>>;
  streamColumns: Array<QTableColumn<StreamWorkItemRow>>;
  streamConnectionState: ReturnType<
    typeof ref<'closed' | 'connecting' | 'open' | 'reconnecting'>
  >;
  streamIsComplete: ReturnType<typeof ref<boolean>>;
  streamRetryCount: ReturnType<typeof ref<number>>;
  streamRows: ReturnType<typeof computed<Array<StreamWorkItemRow>>>;
  streamTotalLoaded: ReturnType<typeof ref<number>>;
}

/**
 * Manage stream state, row mapping, selection sync, and lifecycle for the
 * batch work items view.
 * @returns Reactive state and handlers for the batch stream view.
 */
export function useBatchStream(): UseBatchStreamReturn {
  const traceStore = useTraceStore();
  const { t } = useI18n();
  const {
    errorMessage,
    isLoading,
    streamBatchesProcessed,
    streamConnectionState,
    streamIsComplete,
    streamRetryCount,
    streamTasks,
    streamTotalLoaded,
  } = storeToRefs(traceStore);

  const selectedRows = ref<Array<StreamWorkItemRow>>([]);

  const connectionStateLabel = computed(() =>
    t(`trace.tasks.states.${streamConnectionState.value}`),
  );

  const isBusy = computed(() => isLoading.value);

  const streamRows = computed<Array<StreamWorkItemRow>>(() => {
    const rows: Array<StreamWorkItemRow> = [];

    for (const [index, workItem] of streamTasks.value.entries()) {
      const row = toStreamRow(workItem as Record<string, unknown>, index, t);

      if (row) {
        rows.push(row);
      }
    }

    return rows;
  });

  const availableStatuses = computed<Array<string>>(() => {
    const statuses = new Set<string>();

    for (const row of streamRows.value) {
      statuses.add(row.status);
    }

    return [...statuses].sort((a, b) => a.localeCompare(b));
  });

  const selectedWorkItems = computed<Array<StreamWorkItemRow>>(() => {
    const byWorkItemId = new Map<number, StreamWorkItemRow>();

    for (const row of selectedRows.value) {
      if (!byWorkItemId.has(row.workItemId)) {
        byWorkItemId.set(row.workItemId, row);
      }
    }

    return [...byWorkItemId.values()];
  });

  const streamColumns: Array<QTableColumn<StreamWorkItemRow>> = [
    {
      align: 'left',
      field: 'workItemId',
      label: t('trace.workItem.workItemId'),
      name: 'workItemId',
      sortable: true,
    },
    {
      align: 'left',
      field: 'status',
      label: t('trace.batch.statusColumn'),
      name: 'status',
      sortable: true,
    },
    {
      align: 'left',
      field: 'type',
      label: t('trace.batch.typeColumn'),
      name: 'type',
      sortable: true,
    },
    {
      align: 'left',
      field: 'title',
      label: t('trace.batch.titleColumn'),
      name: 'title',
      sortable: true,
    },
    {
      align: 'left',
      field: 'batchLabel',
      label: t('trace.batch.batchColumn'),
      name: 'batchLabel',
      sortable: true,
    },
    {
      align: 'left',
      field: 'timestamp',
      label: t('trace.batch.timestampColumn'),
      name: 'timestamp',
      sortable: true,
    },
  ];

  watch(
    streamRows,
    (rows) => {
      const availableKeys = new Set(rows.map((row) => row.rowKey));
      selectedRows.value = selectedRows.value.filter((row) =>
        availableKeys.has(row.rowKey),
      );
    },
    { deep: false },
  );

  onBeforeUnmount(() => {
    traceStore.disconnectTaskStream();
  });

  /**
   * Clear selected rows.
   */
  function handleClearSelection(): void {
    selectedRows.value = [];
  }

  /**
   * Reset stream data and selection from the store.
   */
  function handleClearStreamData(): void {
    traceStore.$patch({
      streamRetryCount: 0,
      streamTasks: [],
    });
    handleClearSelection();
  }

  /**
   * Start a new SSE stream connection.
   * @param localErrorReference Ref to reset when connecting.
   */
  function handleConnectStream(
    localErrorReference: ReturnType<typeof ref<string>>,
  ): void {
    const errorReference = localErrorReference;
    errorReference.value = '';
    traceStore.connectTaskStream();
  }

  /**
   * Stop the current SSE stream connection.
   */
  function handleDisconnectStream(): void {
    traceStore.disconnectTaskStream();
  }

  return {
    availableStatuses,
    connectionStateLabel,
    errorMessage,
    handleClearSelection,
    handleClearStreamData,
    handleConnectStream,
    handleDisconnectStream,
    isBusy,
    selectedRows,
    selectedWorkItems,
    streamBatchesProcessed,
    streamColumns,
    streamConnectionState,
    streamIsComplete,
    streamRetryCount,
    streamRows,
    streamTotalLoaded,
  };
}

export const defaultProject = 'MES_X.0';

/**
 *
 * @param value
 */
function normalizeBaseUrl(value: unknown): string {
  if (typeof value !== 'string') {
    return '';
  }

  return value.trim().replace(/\/+$/, '');
}

export const defaultBaseUrl = normalizeBaseUrl(
  import.meta.env.URL_DEPENDENCY_PROTO_BACKEND,
);

import type {
  CommitReference,
  CommitWithTags,
} from '@/work-item-trace/types/trace-api.types.ts';

/**
 * Compare version-like tags numerically.
 * @param leftTag First tag.
 * @param rightTag Second tag.
 * @returns Positive when the left tag is greater.
 */
export function compareVersionTags(leftTag: string, rightTag: string): number {
  const normalizedLeft = leftTag.replace(/^\D*/, '');
  const normalizedRight = rightTag.replace(/^\D*/, '');
  const leftParts = normalizedLeft.split(/\D+/).filter(Boolean).map(Number);
  const rightParts = normalizedRight.split(/\D+/).filter(Boolean).map(Number);
  const maxLength = Math.max(leftParts.length, rightParts.length);

  for (let index = 0; index < maxLength; index += 1) {
    const leftPart = leftParts[index] ?? 0;
    const rightPart = rightParts[index] ?? 0;

    if (leftPart !== rightPart) {
      return leftPart - rightPart;
    }
  }

  return leftTag.localeCompare(rightTag);
}

/**
 * Return the latest tag from a tag list.
 * @param tags Tag candidates.
 * @returns Latest tag or empty string.
 */
export function getLatestTag(tags: Array<string>): string {
  if (tags.length === 0) {
    return '';
  }

  const sortedTags = [...tags].sort(compareVersionTags);
  const latestTag = sortedTags.pop();

  return latestTag ?? '';
}

/**
 * Group commit ids by repository.
 * @param commits Commits with repository names.
 * @returns Map of repository name to unique commit ids.
 */
export function groupCommitIdsByRepo(
  commits: Array<CommitReference>,
): Map<string, Array<string>> {
  const grouped = new Map<string, Array<string>>();

  for (const commit of commits) {
    const repositoryName = commit.repoName || 'unknown';
    const existingCommitIds = grouped.get(repositoryName);

    if (existingCommitIds) {
      if (!existingCommitIds.includes(commit.commitId)) {
        existingCommitIds.push(commit.commitId);
      }
    } else {
      grouped.set(repositoryName, [commit.commitId]);
    }
  }

  return grouped;
}

/**
 * Merge commit tag results by commit id.
 * @param existingCommits Existing commit tag entries.
 * @param incomingCommits Incoming commit tag entries.
 * @returns Merged commit tag entries.
 */
export function mergeCommitTagResults(
  existingCommits: Array<CommitWithTags>,
  incomingCommits: Array<CommitWithTags>,
): Array<CommitWithTags> {
  const commitsById = new Map<string, CommitWithTags>();

  for (const commit of existingCommits) {
    commitsById.set(commit.commitId, commit);
  }

  for (const commit of incomingCommits) {
    commitsById.set(commit.commitId, commit);
  }

  return [...commitsById.values()];
}

import { defaultBaseUrl } from '../config/trace-config';
import type {
  DecisionAggregateResult,
  DecisionDashboardModel,
  DecisionInputPayload,
} from '../types/decision-dashboard.types';

const API_BASE = `${defaultBaseUrl}/decision`;

function fallbackCommitFromTags(
  beforeTags: string[],
  afterTags: string[],
): DecisionDashboardModel['repositories']['withBeforeAndAfter'][number]['commits'] {
  return [
    {
      commitId: '',
      tagBefore: beforeTags,
      tagAfter: afterTags,
      exactTags: [],
    },
  ];
}

function mapToModel(
  result: DecisionAggregateResult,
  payload: DecisionInputPayload,
): DecisionDashboardModel {
  const payloadCommitsByRepo = new Map(
    payload.repositories.map((repo) => [repo.repositoryName, repo.commits]),
  );

  return {
    workItems: {
      done: result.doneWorkItems,
      other: result.otherWorkItems,
    },
    repositories: {
      withBeforeAndAfter: result.reposWithBeforeAndAfter.map((r) => ({
        repositoryName: r.repositoryName,
        commits:
          payloadCommitsByRepo.get(r.repositoryName) ??
          fallbackCommitFromTags(r.beforeTags, r.afterTags ?? []),
      })),
      onlyBefore: result.reposWithOnlyBefore.map((r) => ({
        repositoryName: r.repositoryName,
        commits:
          payloadCommitsByRepo.get(r.repositoryName) ??
          fallbackCommitFromTags(r.beforeTags, []),
      })),
      onlyAfter: (result.reposWithOnlyAfter ?? []).map((r) => ({
        repositoryName: r.repositoryName,
        commits:
          payloadCommitsByRepo.get(r.repositoryName) ??
          fallbackCommitFromTags([], r.afterTags),
      })),
    },
  };
}

export async function aggregateDecision(
  payload: DecisionInputPayload,
): Promise<DecisionDashboardModel> {
  const res = await fetch(`${API_BASE}/aggregate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Decision aggregate failed: ${res.status} ${text}`);
  }

  return mapToModel((await res.json()) as DecisionAggregateResult, payload);
}

import axios, { AxiosError, type AxiosInstance } from 'axios';
import { appLogger } from '@/utils/logger/app-logger.ts';
import {
  defaultBaseUrl,
  defaultProject,
} from '@/work-item-trace/config/trace-config';
import type {
  ApiFailure,
  ApiSuccess,
  BranchesAndTagsResponse,
  CommitTagBatchResponse,
  CommitsByPullRequestData,
  CommitsByWorkItemData,
  PullRequestWorkItemsData,
  RelatedWorkItemsData,
  WorkItem,
} from '@/work-item-trace/types/trace-api.types.ts';

const maxBatchSize = 100;

/**
 * Create and configure an API client for trace endpoints.
 * @returns Configured Axios instance with response interception.
 */
function createApiClient(): AxiosInstance {
  const apiClient = axios.create({
    baseURL: defaultBaseUrl,
    withCredentials: true,
  });

  apiClient.interceptors.response.use(
    (response) => response,
    (error: AxiosError<ApiFailure>) => {
      const loginUrl = error.response?.data?.loginUrl;
      const status = error.response?.status;

      if (
        status === 401 &&
        typeof loginUrl === 'string' &&
        loginUrl.length > 0
      ) {
        globalThis.location.assign(loginUrl);
      }

      return Promise.reject(error);
    },
  );

  return apiClient;
}

/**
 * Extract successful payload data or throw a descriptive error.
 * @param payload API response envelope.
 * @param fallbackMessage Message used when the payload has no error message.
 * @returns Unwrapped payload data when the call succeeds.
 */
function parseSuccessOrThrow<T>(
  payload: ApiFailure | ApiSuccess<T>,
  fallbackMessage: string,
): T {
  if (payload.success) {
    return payload.data;
  }

  throw new Error(payload.message ?? fallbackMessage);
}

/**
 * Build query parameters with project fallback support.
 * @param project Optional Azure DevOps project name.
 * @returns Query parameters including the resolved project name.
 */
function buildParameters(project?: string): URLSearchParams {
  const parameters = new URLSearchParams();
  parameters.set('project', project ?? defaultProject);
  return parameters;
}

/**
 * Split commit IDs into chunks for batched API requests.
 * @param commitIds Commit IDs to split.
 * @param chunkSize Maximum number of commit IDs in each chunk.
 * @returns Array of commit ID chunks.
 */
export function splitCommitIds(
  commitIds: Array<string>,
  chunkSize = maxBatchSize,
): Array<Array<string>> {
  const chunks: Array<Array<string>> = [];
  let index = 0;

  while (index < commitIds.length) {
    chunks.push(commitIds.slice(index, index + chunkSize));
    index += chunkSize;
  }

  return chunks;
}

const apiClient = createApiClient();

/**
 * Fetch commits linked to a pull request.
 * @param prId Pull request identifier.
 * @param project Optional Azure DevOps project name.
 * @returns Commits associated with the specified pull request.
 */
export async function getCommitsByPullRequest(
  prId: number,
  project?: string,
): Promise<CommitsByPullRequestData> {
  appLogger.log(
    `[API] Fetching commits for pull request ${prId}, project: ${project}`,
  );
  const parameters = buildParameters(project);

  try {
    const response = await apiClient.get<ApiSuccess<CommitsByPullRequestData>>(
      `/commits/pullrequests/${prId}`,
      { params: parameters },
    );

    appLogger.log(
      `[API] Successfully retrieved commits for PR ${prId}: ${response.data.success}`,
    );
    return parseSuccessOrThrow(
      response.data,
      'Unable to load commits by pull request.',
    );
  } catch (error) {
    appLogger.error(
      `[API] Error fetching commits for PR ${prId}`,
      error instanceof Error ? error.stack : String(error),
    );
    throw error;
  }
}

/**
 * Fetch commits linked to a work item.
