  }
}

/**
 * Fetch branches and tags that reference a commit.
 * @param commitId Commit identifier.
 * @param project Azure DevOps project name.
 * @param repositoryName Repository name containing the commit.
 * @returns Branches and tags lookup result for the commit.
 */
export async function getCommitTags(
  commitId: string,
  project: string,
  repositoryName: string,
): Promise<BranchesAndTagsResponse> {
  appLogger.log(
    `[API] Fetching tags for commit ${commitId}, repo: ${repositoryName}, project: ${project}`,
  );
  const parameters = new URLSearchParams();
  parameters.set('commitId', commitId);
  parameters.set('project', project);
  parameters.set('repositoryName', repositoryName);

  try {
    const response = await apiClient.get<BranchesAndTagsResponse>(
      '/commits/tags',
      {
        params: parameters,
      },
    );

    appLogger.log(
      `[API] Successfully retrieved tags for commit ${commitId}: ${response.data.success}`,
    );

    if (
      !response.data.success &&
      typeof response.data.message === 'string' &&
      response.data.message.length > 0
    ) {
      appLogger.warn(
        `[API] Tag retrieval failed with message: ${response.data.message}`,
      );
      throw new Error(response.data.message);
    }

    return response.data;
  } catch (error) {
    appLogger.error(
      `[API] Error fetching tags for commit ${commitId}`,
      error instanceof Error ? error.stack : String(error),
    );
    throw error;
  }
}

