 */
export async function getPullRequestWorkItems(
  prId: number,
  project?: string,
): Promise<PullRequestWorkItemsData> {
  appLogger.log(
    `[API] Fetching work items for pull request ${prId}, project: ${project}`,
  );
  const parameters = buildParameters(project);

  try {
    const response = await apiClient.get<ApiSuccess<PullRequestWorkItemsData>>(
      `/pullrequests/${prId}/workitems`,
      { params: parameters },
    );

    appLogger.log(
      `[API] Successfully retrieved work items for PR ${prId}: ${response.data.success}`,
    );
    return parseSuccessOrThrow(
      response.data,
      'Unable to load work items by pull request.',
    );
  } catch (error) {
    appLogger.error(
      `[API] Error fetching work items for PR ${prId}`,
      error instanceof Error ? error.stack : String(error),
    );
    throw error;
  }
}

