/**
 * Fetch available branches and tags for a repository.
 * @param project Azure DevOps project name.
 * @param repositoryName Repository name.
 * @returns Branch and tag data for the repository.
 */
export async function getRepositoryBranchesAndTags(
  project: string,
  repositoryName: string,
): Promise<BranchesAndTagsResponse> {
  appLogger.log(
    `[API] Fetching branches and tags for repo ${repositoryName}, project: ${project}`,
  );
  const parameters = new URLSearchParams();
  parameters.set('project', project);
  parameters.set('repositoryName', repositoryName);

  try {
    const response = await apiClient.get<BranchesAndTagsResponse>(
      '/commits/branches',
      {
        params: parameters,
      },
    );

    appLogger.log(
      `[API] Successfully retrieved branches and tags for repo ${repositoryName}: ${response.data.success}`,
    );

    if (
      !response.data.success &&
      typeof response.data.message === 'string' &&
      response.data.message.length > 0
    ) {
      appLogger.warn(
        `[API] Branches/tags retrieval failed with message: ${response.data.message}`,
      );
      throw new Error(response.data.message);
    }

    return response.data;
  } catch (error) {
    appLogger.error(
      `[API] Error fetching branches and tags for repo ${repositoryName}`,
      error instanceof Error ? error.stack : String(error),
    );
    throw error;
  }
}

