export { maxBatchSize };

export { defaultProject } from '@/work-item-trace/config/trace-config';

import { defineStore } from 'pinia';
import {
  defaultProject,
  defaultBaseUrl,
} from '@/work-item-trace/config/trace-config';
import {
  getCommitTags,
  getCommitTagsBatch,
  getCommitsByPullRequest,
  getCommitsByWorkItem,
  getPullRequestWorkItems,
  getRelatedWorkItems,
  getRepositoryBranchesAndTags,
  getWorkItemById,
  splitCommitIds,
} from '@/work-item-trace/services/trace-api.service.ts';
import type {
  BranchesAndTagsResponse,
  CommitReference,
  CommitTagBatchItem,
  CommitsByPullRequestData,
  CommitsByWorkItemData,
  PullRequestWorkItemsData,
  RelatedWorkItemsData,
  TaskStreamMessage,
  WorkItem,
} from '@/work-item-trace/types/trace-api.types.ts';

interface TraceState {
  batchTagResults: Record<string, CommitTagBatchItem>;
  commitsByPullRequest: CommitsByPullRequestData | undefined;
  commitsByWorkItem: CommitsByWorkItemData | undefined;
  commitTagContextByCommitId: Record<string, BranchesAndTagsResponse>;
  errorMessage: string;
  isLoading: boolean;
  project: string;
  pullRequestWorkItems: PullRequestWorkItemsData | undefined;
  relatedWorkItems: RelatedWorkItemsData | undefined;
  repositoryBranchesAndTags: BranchesAndTagsResponse | undefined;
  streamBatchesProcessed: number;
  streamConnectionState: 'closed' | 'connecting' | 'open' | 'reconnecting';
  streamIsComplete: boolean;
  streamRetryCount: number;
  streamTasks: Array<Record<string, unknown>>;
  streamTotalLoaded: number;
  workItem: WorkItem | undefined;
}

let taskStreamSource: EventSource | undefined;

/**
 * Extract a user-facing error message.
 * @param error Unknown error value.
 * @returns Error message when available, otherwise an empty string.
 */
function toErrorMessage(error: unknown): string {
  if (error instanceof Error && error.message.length > 0) {
    return error.message;
  }

  return '';
}

/**
 * Normalize project input by trimming and falling back to default.
 * @param project Raw project name.
 * @returns Normalized project value.
 */
function normalizeProject(project: string): string {
  const trimmed = project.trim();
  return trimmed.length > 0 ? trimmed : defaultProject;
}

export const useTraceStore = defineStore('traceStore', {
  actions: {
    connectTaskStream(): void {
      this.disconnectTaskStream();
      this.clearError();

      if (defaultBaseUrl.length === 0) {
        this.errorMessage =
          'Missing URL_DEPENDENCY_PROTO_BACKEND environment variable.';
        return;
      }

      this.streamConnectionState = 'connecting';
      this.streamRetryCount = 0;
      this.streamTasks = [];
      this.streamTotalLoaded = 0;
      this.streamBatchesProcessed = 0;
      this.streamIsComplete = false;

      taskStreamSource = new EventSource(
        `${defaultBaseUrl}/workitem/tasks/stream`,
        {
          withCredentials: true,
        },
      );

      taskStreamSource.addEventListener('open', () => {
        this.streamConnectionState = 'open';
      });

      taskStreamSource.addEventListener('error', () => {
        this.streamConnectionState = 'reconnecting';
        this.streamRetryCount += 1;
      });

      taskStreamSource.addEventListener(
        'message',
        (event: MessageEvent<string>) => {
          try {
            const payload = JSON.parse(event.data) as TaskStreamMessage;

            if ('error' in payload) {
              this.errorMessage = payload.error;
              this.streamIsComplete = true;
              this.disconnectTaskStream();
              return;
            }

            if ('complete' in payload && payload.complete) {
              this.streamBatchesProcessed = payload.batchesProcessed;
              this.streamIsComplete = true;
              this.disconnectTaskStream();
              return;
            }

            if ('batch' in payload && Array.isArray(payload.batch)) {
              const receivedAt = new Date().toISOString();
              const annotatedBatch = payload.batch.map((task) => ({
                ...task,
                streamBatchNumber: payload.batchNumber,
                streamReceivedAt: receivedAt,
              }));

              this.streamTasks = [...this.streamTasks, ...annotatedBatch];
              this.streamTotalLoaded = payload.totalLoaded;
              this.streamBatchesProcessed = payload.batchNumber;
            }
          } catch (error) {
            this.errorMessage =
              error instanceof Error
                ? error.message
                : 'Failed to parse stream message';
          }
        },
      );
    },

    disconnectTaskStream(): void {
      if (taskStreamSource) {
        taskStreamSource.close();
        taskStreamSource = undefined;
      }

      this.streamConnectionState = 'closed';
    },

    clearError(): void {
      this.errorMessage = '';
    },

    clearState(): void {
      this.batchTagResults = {};
      this.commitTagContextByCommitId = {};
      this.commitsByPullRequest = undefined;
      this.commitsByWorkItem = undefined;
      this.errorMessage = '';
      this.pullRequestWorkItems = undefined;
      this.relatedWorkItems = undefined;
      this.repositoryBranchesAndTags = undefined;
      this.streamBatchesProcessed = 0;
      this.streamConnectionState = 'closed';
      this.streamIsComplete = false;
      this.streamRetryCount = 0;
      this.streamTasks = [];
      this.streamTotalLoaded = 0;
      this.workItem = undefined;
    },

    async loadBatchCommitContext(
      commitIds: Array<string>,
      project: string,
      repositoryName: string,
    ): Promise<void> {
      this.clearError();
      this.isLoading = true;

      try {
        const normalizedProject = normalizeProject(project);
        const normalizedRepositoryName = repositoryName.trim();
        this.project = normalizedProject;

        const cleanCommitIds = commitIds
          .map((commitId) => commitId.trim())
          .filter((commitId) => commitId.length > 0);
        const chunks = splitCommitIds(cleanCommitIds);
        const responses = await Promise.all(
          chunks.map(async (chunk) =>
            getCommitTagsBatch(
              chunk,
              normalizedProject,
              normalizedRepositoryName,
            ),
          ),
        );
        const mergedResults: Record<string, CommitTagBatchItem> = {};

        for (const response of responses) {
          Object.assign(mergedResults, response.results);
        }

        this.batchTagResults = mergedResults;
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
      } finally {
        this.isLoading = false;
      }
    },

    async loadPullRequestTrace(prId: number, project: string): Promise<void> {
      this.clearError();
      this.isLoading = true;

      try {
        const normalizedProject = normalizeProject(project);
        this.project = normalizedProject;

        const [commits, workItems] = await Promise.all([
          getCommitsByPullRequest(prId, normalizedProject),
          getPullRequestWorkItems(prId, normalizedProject),
        ]);

        this.commitsByPullRequest = commits;
        this.pullRequestWorkItems = workItems;

        await this.resolveTagContextForCommits(
          commits.commits,
          normalizedProject,
        );
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
      } finally {
        this.isLoading = false;
      }
    },

    async loadRelatedWorkItems(
      workItemId: number,
      project: string,
    ): Promise<void> {
      this.clearError();
      this.isLoading = true;

      try {
        const normalizedProject = normalizeProject(project);
        this.project = normalizedProject;
        this.relatedWorkItems = await getRelatedWorkItems(
          workItemId,
          normalizedProject,
        );
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
      } finally {
        this.isLoading = false;
      }
    },

    async loadRelatedWorkItemsBatch(
      workItemIds: Array<number>,
      project: string,
    ): Promise<Array<RelatedWorkItemsData>> {
      this.clearError();
      this.isLoading = true;

      try {
        const normalizedProject = normalizeProject(project);
        this.project = normalizedProject;

        const normalizedWorkItemIds = [...new Set(workItemIds)]
          .map(Number)
          .filter(
            (workItemId) => Number.isInteger(workItemId) && workItemId > 0,
          );

        return await Promise.all(
          normalizedWorkItemIds.map(async (workItemId) =>
            getRelatedWorkItems(workItemId, normalizedProject),
          ),
        );
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
        return [];
      } finally {
        this.isLoading = false;
      }
    },

    async fetchRelatedWorkItemsResult(
      workItemId: number,
      project: string,
    ): Promise<RelatedWorkItemsData | undefined> {
      this.clearError();

      try {
        const normalizedProject = normalizeProject(project);
        this.project = normalizedProject;

        if (!Number.isInteger(workItemId) || workItemId <= 0) {
          return undefined;
        }

        return await getRelatedWorkItems(workItemId, normalizedProject);
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
        return undefined;
      }
    },

    async loadRepositoryContext(
      project: string,
      repositoryName: string,
    ): Promise<void> {
      this.clearError();
      this.isLoading = true;

      try {
        const normalizedProject = normalizeProject(project);
        this.project = normalizedProject;
        this.batchTagResults = {};
        this.repositoryBranchesAndTags = await getRepositoryBranchesAndTags(
          normalizedProject,
          repositoryName.trim(),
        );
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
      } finally {
        this.isLoading = false;
      }
    },

    async loadSingleCommitContext(
      commitId: string,
      project: string,
      repositoryName: string,
    ): Promise<void> {
      this.clearError();
      this.isLoading = true;

      try {
        const normalizedProject = normalizeProject(project);
        const normalizedCommitId = commitId.trim();
        const normalizedRepositoryName = repositoryName.trim();

        this.project = normalizedProject;
        this.batchTagResults = {};
        this.commitTagContextByCommitId = {};

        const context = await getCommitTags(
          normalizedCommitId,
          normalizedProject,
          normalizedRepositoryName,
        );
        this.commitTagContextByCommitId = {
          [normalizedCommitId]: context,
        };
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
      } finally {
        this.isLoading = false;
      }
    },

    async loadWorkItemTrace(
      workItemId: number,
      project: string,
    ): Promise<void> {
      this.clearError();
      this.isLoading = true;

      try {
        const normalizedProject = normalizeProject(project);
        this.project = normalizedProject;

        const [commits, workItem] = await Promise.all([
          getCommitsByWorkItem(workItemId, normalizedProject),
          getWorkItemById(workItemId),
        ]);

        this.commitsByWorkItem = commits;
        this.workItem = workItem;

        await this.resolveTagContextForCommits(
          commits.commits,
          normalizedProject,
        );
      } catch (error) {
        this.errorMessage = toErrorMessage(error);
      } finally {
        this.isLoading = false;
      }
    },

    async resolveTagContextForCommits(
      commits: Array<CommitReference>,
      project: string,
    ): Promise<void> {
      const groupedByRepository = new Map<string, Array<string>>();

      for (const commit of commits) {
        const repositoryCommits =
          groupedByRepository.get(commit.repoName) ?? [];
        repositoryCommits.push(commit.commitId);
        groupedByRepository.set(commit.repoName, repositoryCommits);
      }

      const resolvedContext: Record<string, BranchesAndTagsResponse> = {};
      const repositoryPromises = [...groupedByRepository.entries()].map(
        async ([repositoryName, repositoryCommitIds]) => {
          if (repositoryCommitIds.length === 1) {
            const commitId = repositoryCommitIds[0];
            const context = await getCommitTags(
              commitId,
              project,
              repositoryName,
            );
            return {
              [commitId]: context,
            };
          }

          const commitChunks = splitCommitIds(repositoryCommitIds);
          const batchResponses = await Promise.all(
            commitChunks.map(async (chunk) =>
              getCommitTagsBatch(chunk, project, repositoryName),
            ),
          );
          const repositoryContext: Record<string, BranchesAndTagsResponse> = {};

          for (const [chunkIndex, chunk] of commitChunks.entries()) {
            const batchResponse = batchResponses[chunkIndex];

            for (const commitId of chunk) {
              const batchItem: CommitTagBatchItem | undefined =
                batchResponse.results[commitId];
              repositoryContext[commitId] = {
                branches: batchItem?.foundInBranch ? [repositoryName] : [],
                success: true,
                tags: batchItem?.exactTags ?? [],
              };
            }
          }

          return repositoryContext;
        },
      );

      const repositoryContextList = await Promise.all(repositoryPromises);

      for (const repositoryContext of repositoryContextList) {
        Object.assign(resolvedContext, repositoryContext);
      }

      this.commitTagContextByCommitId = resolvedContext;
    },
  },

  state: (): TraceState => ({
    batchTagResults: {},
    commitTagContextByCommitId: {},
    commitsByPullRequest: undefined,
    commitsByWorkItem: undefined,
    errorMessage: '',
    isLoading: false,
    project: defaultProject,
    pullRequestWorkItems: undefined,
    relatedWorkItems: undefined,
    repositoryBranchesAndTags: undefined,
    streamBatchesProcessed: 0,
    streamConnectionState: 'closed',
    streamIsComplete: false,
    streamRetryCount: 0,
    streamTasks: [],
    streamTotalLoaded: 0,
    workItem: undefined,
  }),
});

